import { z } from 'zod';
import type { TransferState } from './files';

export const MESSAGE_MAX_CHARS = 8000;
export const DRAFT_MAX_CHARS = MESSAGE_MAX_CHARS;
export const PAGE_SIZE_MAX = 200;

/** UUIDv7 as generated by MeshTalk devices. */
export const messageIdSchema = z
  .string()
  .regex(
    /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/,
    'Invalid message ID',
  );

export const conversationIdSchema = z
  .string()
  .regex(/^(d:[A-Z2-7]{52}|g:[0-9a-f-]{36})$/, 'Invalid conversation');

export const messageBodySchema = z
  .string()
  .max(MESSAGE_MAX_CHARS, `Messages can be at most ${MESSAGE_MAX_CHARS} characters`)
  .refine((s) => s.trim().length > 0, 'Message is empty');

/** A single emoji (possibly with modifiers / ZWJ sequences). */
export const emojiSchema = z
  .string()
  .min(1)
  .max(32)
  .regex(/^(?:\p{Extended_Pictographic}|\p{Emoji_Component}|‍|️)+$/u, 'Not an emoji');

export type MessageKind = 'text' | 'file' | 'voice' | 'system';
/** Own messages: pending → delivered → read. Incoming: received. */
export type MessageStatus = 'pending' | 'delivered' | 'read' | 'received' | 'failed';

export interface ReactionSummary {
  emoji: string;
  count: number;
  mine: boolean;
  names: string[];
}

export interface ReplyPreview {
  id: string;
  senderName: string;
  excerpt: string;
  deleted: boolean;
}

export interface AttachmentSummary {
  fileId: string;
  name: string;
  size: number;
  mime: string;
  /** Duration for voice messages. */
  durationMs: number | null;
  state: TransferState;
  bytesDone: number;
  /** Incoming only: what the user may do next. */
  direction: 'incoming' | 'outgoing';
  /** Raster image / audio / video that can be previewed inline. */
  previewKind: 'image' | 'audio' | 'video' | null;
  /** Executables are never opened by MeshTalk, only revealed in the folder. */
  executable: boolean;
  error: string | null;
  /** True once the file is on this device and verified. */
  available: boolean;
}

export interface ChatMessage {
  id: string;
  conversationId: string;
  senderDeviceId: string;
  senderName: string;
  fromMe: boolean;
  kind: MessageKind;
  body: string;
  replyTo: ReplyPreview | null;
  sentAt: number;
  editedAt: number | null;
  deletedAt: number | null;
  status: MessageStatus;
  reactions: ReactionSummary[];
  attachment: AttachmentSummary | null;
  /** Mentions of the local user (groups). */
  mentionsMe: boolean;
}

export interface ConversationSummary {
  id: string;
  kind: 'direct' | 'group';
  title: string;
  peerDeviceId: string | null;
  online: boolean;
  pinned: boolean;
  archived: boolean;
  muted: boolean;
  unreadCount: number;
  draft: string;
  lastMessage: { excerpt: string; sentAt: number; fromMe: boolean; senderName: string } | null;
  /** Null when sending is allowed; otherwise the reason it isn't. */
  cannotSendReason: string | null;
  /** Messages waiting in this device's outbox for this conversation. */
  pendingCount: number;
}

export interface MessagePage {
  messages: ChatMessage[];
  hasMore: boolean;
}

export interface SearchHit {
  messageId: string;
  conversationId: string;
  conversationTitle: string;
  senderName: string;
  sentAt: number;
  /** Excerpt with matches wrapped in \u0001 … \u0002 markers (rendered safely as <mark>). */
  snippet: string;
}

export const cursorSchema = z.object({ sentAt: z.number().int(), id: messageIdSchema }).strict();

export const listMessagesSchema = z
  .object({
    conversationId: conversationIdSchema,
    before: cursorSchema.nullable(),
    limit: z.number().int().min(1).max(PAGE_SIZE_MAX),
  })
  .strict();

export const sendMessageSchema = z
  .object({
    conversationId: conversationIdSchema,
    body: messageBodySchema,
    replyToId: messageIdSchema.nullable(),
    mentions: z
      .array(z.string().regex(/^[A-Z2-7]{52}$/))
      .max(50)
      .optional(),
  })
  .strict();

export const editMessageSchema = z
  .object({ messageId: messageIdSchema, body: messageBodySchema })
  .strict();
export const deleteMessageSchema = z
  .object({ messageId: messageIdSchema, forEveryone: z.boolean() })
  .strict();
export const reactSchema = z
  .object({ messageId: messageIdSchema, emoji: emojiSchema, on: z.boolean() })
  .strict();
export const conversationRefSchema = z.object({ conversationId: conversationIdSchema }).strict();
export const setActiveSchema = z
  .object({ conversationId: conversationIdSchema.nullable() })
  .strict();
export const setDraftSchema = z
  .object({ conversationId: conversationIdSchema, draft: z.string().max(DRAFT_MAX_CHARS) })
  .strict();
export const setFlagsSchema = z
  .object({
    conversationId: conversationIdSchema,
    pinned: z.boolean().optional(),
    archived: z.boolean().optional(),
    muted: z.boolean().optional(),
  })
  .strict();
export const listConversationsSchema = z.object({ archived: z.boolean() }).strict();
export const searchSchema = z
  .object({
    query: z.string().trim().min(1).max(200),
    conversationId: conversationIdSchema.nullable(),
  })
  .strict();

export function directConversationId(deviceId: string): string {
  return `d:${deviceId}`;
}

export const messagePositionSchema = z
  .object({ conversationId: conversationIdSchema, messageId: messageIdSchema })
  .strict();
